พิจารณาโค้ดต่อไปนี้:
const MAX_VOLT = 240;
function checkVolt(v) {
  if (v > MAX_VOLT) {
    return 'อันตราย';
  } else if (v >= 235) {
    return 'เฝ้าระวัง';
  } else {
    return 'ปกติ';
  }
}
document.getElementById('status').textContent = checkVolt(240);
ผลลัพธ์ที่แสดงใน #status คือข้อใด

API ตอบกลับ JSON ดังนี้:
{ "line": "A", "electric": { "voltage": 248.5, "current": 16.2 }, "water": { "flow": 3.1 } }
หลังแปลงเป็นตัวแปร data ด้วย const data = await res.json(); แล้ว หากต้องการอ่านค่าอัตราการไหลของน้ำ (3.1) ต้องเขียนอย่างไร
